set -e; gh api 'repos/MichalMatu/local-climate-link-starter/releases?per_page=100' >/tmp/lcl-releases-before-publish.json; python3 -c 'import hashlib,json,pathlib; rs=json.load(open("/tmp/lcl-releases-before-publish.json")); hits=[r for r in rs if r.get("tag_name")=="v2.0.10" and r.get("draft") is True]; assert len(hits)==1,hits; r=hits[0]; assets={a.get("name"):a for a in r.get("assets",[])}; exp=["local-climate-link-v2.0.10-android-release.apk","local-climate-link-v2.0.10-android-release.aab","local-climate-link-v2.0.10-sha256.txt"]; assert sorted(assets)==sorted(exp),(sorted(assets),sorted(exp)); base=pathlib.Path("artifacts/releases/v2.0.10");
for name in exp:
 digest=hashlib.sha256((base/name).read_bytes()).hexdigest(); remote=assets[name].get("digest"); assert remote in (None,"sha256:"+digest),(name,remote,digest)
open("/tmp/lcl-v2010-release-id","w").write(str(r["id"])); print("DRAFT_RELEASE_ID="+str(r["id"])); print("DRAFT_ASSETS_VERIFIED=true")'

