for name in exp:
 digest=hashlib.sha256((base/name).read_bytes()).hexdigest(); remote=assets[name].get("digest"); assert remote in (None,"sha256:"+digest),(name,remote,digest)
print("FINAL_RELEASE_IMMUTABLE=true"); print("FINAL_RELEASE_ASSETS="+",".join(sorted(assets))); print("FINAL_RELEASE_URL="+str(r.get("html_url"))); print("FINAL_RELEASE_PUBLISHED_AT="+str(r.get("published_at")))'
